from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_DOWN, ROUND_UP, InvalidOperation

_MINOR_UNITS = {
    "EUR": 2,
    "USD": 2,
    "GBP": 2,
    "CHF": 2,
    "AUD": 2,
    "CAD": 2,
    "JPY": 0,
    "KRW": 0,
    "VND": 0,
    "BHD": 3,
    "KWD": 3,
    "OMR": 3,
    "TND": 3,
    "JOD": 3,
}

_MODES = {
    "HALF_UP": ROUND_HALF_UP,
    "HALF_EVEN": ROUND_HALF_EVEN,
    "DOWN": ROUND_DOWN,
    "UP": ROUND_UP,
}

def round_money(amount: str, currency: str, mode: str = "HALF_UP") -> Decimal:
    # Validate types strictly; float must never be used.
    if not isinstance(amount, str):
        raise ValueError("amount must be a decimal string")
    if not isinstance(currency, str):
        raise ValueError("currency must be a string")
    if not isinstance(mode, str):
        raise ValueError("mode must be a string")
    # Parse amount with Decimal.
    try:
        d = Decimal(amount)
    except (InvalidOperation, ValueError, AttributeError, TypeError, ArithmeticError):
        raise ValueError("invalid amount")
    # Must be finite.
    try:
        finite = d.is_finite()
    except Exception:
        raise ValueError("invalid amount")
    if not finite:
        raise ValueError("amount must be finite")
    # Currency lookup case-insensitive.
    ckey = currency.upper()
    if ckey not in _MINOR_UNITS:
        raise ValueError("unsupported currency")
    places = _MINOR_UNITS[ckey]
    # Mode lookup case-insensitive.
    mkey = mode.upper()
    if mkey not in _MODES:
        raise ValueError("unsupported mode")
    rounding = _MODES[mkey]
    # Build quantum with exact exponent.
    if places == 0:
        quantum = Decimal("1")
    elif places == 2:
        quantum = Decimal("0.01")
    elif places == 3:
        quantum = Decimal("0.001")
    else:
        quantum = Decimal("0." + "0" * (places - 1) + "1")
    return d.quantize(quantum, rounding=rounding)
